const serviceAreaZips = new Set([
  '33602', '33603', '33604', '33605',
  '33606', '33607', '33609', '33611',
  '33614', '33616', '33619', '33629'
]);

return $input.all().map((item) => {
  const p = item.json.properties ?? item.json;

  const contactId = String(item.json.id ?? p.hs_object_id ?? '');
  const firstName = p.firstname || 'Lead';
  const zip = String(p.zip ?? '').trim();
  const serviceType = String(p.service_type ?? '').trim();
  const frequency = String(p.cleaning_frequency ?? '').trim();
  const squareFeet = Number(p.home_square_footage || 0);
  const preferredDate = p.preferred_service_date || null;

  let score = 0;

  const breakdown = {
    zip_fit: 0,
    service_value: 0,
    frequency_value: 0,
    home_fit: 0,
    urgency: 0,
  };

  // ZIP fit: maximum 25 points
  const isInServiceArea = serviceAreaZips.has(zip);

  if (isInServiceArea) {
    breakdown.zip_fit = 25;
  }

  // Service value: maximum 20 points
  const service = serviceType.toLowerCase();

  if (service.includes('recurring')) {
    breakdown.service_value = 20;
  } else if (service.includes('deep') || service.includes('move')) {
    breakdown.service_value = 15;
  } else if (service.includes('standard')) {
    breakdown.service_value = 10;
  } else if (serviceType) {
    breakdown.service_value = 5;
  }

  // Frequency/retention value: maximum 20 points
  const cadence = frequency.toLowerCase();

  if (cadence.includes('weekly') && !cadence.includes('two')) {
    breakdown.frequency_value = 20;
  } else if (
    cadence.includes('two weeks') ||
    cadence.includes('biweekly')
  ) {
    breakdown.frequency_value = 15;
  } else if (cadence.includes('monthly')) {
    breakdown.frequency_value = 10;
  } else if (
    cadence.includes('one-time') ||
    cadence.includes('one time')
  ) {
    breakdown.frequency_value = 5;
  } else if (frequency) {
    breakdown.frequency_value = 5;
  }

  // Home/job fit: maximum 15 points
  if (squareFeet >= 1000 && squareFeet <= 3500) {
    breakdown.home_fit = 15;
  } else if (squareFeet > 3500) {
    breakdown.home_fit = 10;
  } else if (squareFeet > 0) {
    breakdown.home_fit = 8;
  }

  // Urgency: maximum 20 points
  let daysUntilService = null;

  if (preferredDate) {
    const serviceDate = new Date(`${preferredDate}T00:00:00Z`);
    const currentDate = new Date();

    if (!Number.isNaN(serviceDate.getTime())) {
      daysUntilService = Math.ceil(
        (serviceDate.getTime() - currentDate.getTime()) / 86400000
      );

      if (daysUntilService < 0) {
        breakdown.urgency = 0;
      } else if (daysUntilService <= 7) {
        breakdown.urgency = 20;
      } else if (daysUntilService <= 14) {
        breakdown.urgency = 15;
      } else if (daysUntilService <= 30) {
        breakdown.urgency = 10;
      } else {
        breakdown.urgency = 5;
      }
    }
  }

  score = Object.values(breakdown).reduce(
    (total, points) => total + points,
    0
  );

  const missingFields = [];

  if (!zip) missingFields.push('ZIP code');
  if (!serviceType) missingFields.push('service type');
  if (!frequency) missingFields.push('cleaning frequency');
  if (!preferredDate) missingFields.push('preferred service date');
  if (!p.email && !p.phone) missingFields.push('contact method');

  let qualificationStatus;
  let disqualificationReason = '';
  let nextBestAction;

  if (missingFields.length > 0) {
    qualificationStatus = 'Needs More Information';
    nextBestAction = 'Request More Information';
  } else if (!isInServiceArea) {
    qualificationStatus = 'Unqualified';
    disqualificationReason = 'Outside Service Area';
    nextBestAction = 'Mark Unqualified';
  } else if (score >= 85) {
    qualificationStatus = 'Qualified';
    nextBestAction = 'Call Immediately';
  } else if (score >= 70) {
    qualificationStatus = 'Qualified';
    nextBestAction = 'Send Estimate';
  } else if (score >= 50) {
    qualificationStatus = 'Nurture';
    nextBestAction = 'Begin Nurture Sequence';
  } else {
    qualificationStatus = 'Needs More Information';
    nextBestAction = 'Human Review';
  }

  const qualificationSummary =
    `SIMULATED rule-based qualification: ${firstName} scored ${score}/100. ` +
    `ZIP ${zip || 'missing'}; service: ${serviceType || 'missing'}; ` +
    `frequency: ${frequency || 'missing'}; home size: ` +
    `${squareFeet || 'missing'} sq ft; status: ${qualificationStatus}. ` +
    `Recommended action: ${nextBestAction}.`;

  return {
    json: {
      ...item.json,
      contact_id: contactId,
      lead_score: score,
      qualification_status: qualificationStatus,
      disqualification_reason: disqualificationReason,
      next_best_action: nextBestAction,
      qualification_summary: qualificationSummary,
      score_breakdown: breakdown,
      days_until_service: daysUntilService,
    },
  };
});
